Outputs.HeadOffset:
if (regulateHeadPiezo){
    newOffset := HeadRegulator(abs(AveragedMechanical[1]));
    regulateSamplePiezo := false;
}
else{
    regulateSamplePiezo := true;
    newOffset := 0.0;
}
return [newOffset];

Outputs.Mechanical:
var v[6];

for (var n := 0; n < 6; n += 1) {
    switch {
        case (n == 5):
            v[n] := (9000-HeadOffset)*headZCalibration;
        default:
            v[n] := AveragedMechanical[n];
    }

}

return [v];

Arriving.M:
if (m1aInContact < 0.0){
    m1aInContact := abs(AveragedMechanical[1]);
    Scan.Arriving();
}
if (not (regulateHeadPiezo))
    regulateHeadPiezo := true;
return [nan];

Departing.M:
if (regulateHeadPiezo)
    Scan.Departing();
regulateHeadPiezo := false;
newOffset := 0.0;
return[nan];
